MAP
    NAME "ogf"
    EXTENT 42250.00012 21170.00012000001 295170.00012 167700.00012
    SIZE 800 800

    SHAPEPATH "/media/Data10/Forestimator/Autre/"
    IMAGECOLOR 255 255 255
    IMAGETYPE "PNG"
    TRANSPARENT ON

    PROJECTION
        "init=epsg:31370"
    END

    WEB
        METADATA
            "wms_label" "Serveur WMS de diverses cartes relatives aux forets subnaturelles matures"
            "wms_title" "Cartes de ciblage des OGF potentielles"
            "wms_onlineresource" "http://gxgfservcarto.gxabt.ulg.ac.be/cgi-bin/ogf"
            "wms_service_onlineresource" "http://gxgfservcarto.gxabt.ulg.ac.be/cgi-bin/ogf"
            "wms_srs" "EPSG:31370"
            "wms_enable_request" "*"
            "wms_getfeatureinfo_formatlist" "text/plain,application/vnd.ogc.gml,text/html"
        END
    END


    # -------------------------------------------------------------------------
    # Produit principal : cartographie polygonale de ciblage
    # Colonne utilisee : Classe ; seules les classes 1 et 2 sont dessinees.
    # Les valeurs 0 et NA / NULL ne correspondent a aucune classe et restent transparentes.
    # -------------------------------------------------------------------------
    LAYER
        NAME "ogf_ciblage_polygones"
        TYPE POLYGON
        STATUS ON

        CONNECTIONTYPE OGR
        CONNECTION "ogf_ciblage_polygones.gpkg"
        DATA "ogf_ciblage_polygones"

        PROJECTION
            "init=epsg:31370"
        END

        CLASSITEM "Classe"

        CLASS
            NAME "Classe 1"
            EXPRESSION "1"
            STYLE
                COLOR 0 90 35
                OUTLINECOLOR 0 70 25
            END
        END

        CLASS
            NAME "Classe 2"
            EXPRESSION "2"
            STYLE
                COLOR 145 200 110
                OUTLINECOLOR 90 150 70
            END
        END

        METADATA
            "wms_title" "Cartographie de ciblage des OGF potentielles"
            "wms_abstract" "Couche principale de ciblage des peuplements potentiellement favorables au statut OGF. Les classes 1 et 2 identifient des secteurs prioritaires pour la prospection. Les valeurs 0 et NA ne sont pas dessinees. Le statut OGF doit etre confirme sur le terrain."
            "wms_srs" "EPSG:31370"
            "gml_include_items" "all"
            "wms_include_items" "all"
        END
    END


    # -------------------------------------------------------------------------
    # Aide terrain : cas stationnel indicatif
    # Valeur 1 transparente ; valeur 2 rouge.
    # -------------------------------------------------------------------------
    LAYER
        NAME "ogf_cas_stationnel"
        TYPE RASTER
        STATUS ON

        DATA "ogf_cas_stationnel.tif"

        PROJECTION
            "init=epsg:31370"
        END

        PROCESSING "BANDS=1"
        CLASSITEM "[pixel]"

        CLASS
            NAME "Cas 2 potentiel - a verifier sur le terrain"
            EXPRESSION "2"
            STYLE
                COLOR 220 0 0
            END
        END

        CLASS
            NAME "Cas 1 - transparent"
            EXPRESSION "1"
            STYLE
                COLOR 255 255 255
                OPACITY 0
            END
        END

        CLASS
            NAME "Valeur 0 ou hors information - transparent"
            EXPRESSION "0"
            STYLE
                COLOR 255 255 255
                OPACITY 0
            END
        END

        METADATA
            "wms_title" "Cas stationnel indicatif"
            "wms_abstract" "Couche indicative d'aide a l'attribution du cas stationnel. La valeur 2 signale une station susceptible de relever du cas 2 et doit etre verifiee sur le terrain. La valeur 1 est transparente."
            "wms_srs" "EPSG:31370"
        END
    END


    # -------------------------------------------------------------------------
    # Raster intermediaire q70 : 0 transparent ; 1 noir.
    # -------------------------------------------------------------------------
    LAYER
        NAME "ogf_q70_pixels_retenus"
        TYPE RASTER
        STATUS ON

        DATA "ogf_q70_pixels_retenus.tif"

        PROJECTION
            "init=epsg:31370"
        END

        PROCESSING "BANDS=1"
        CLASSITEM "[pixel]"

        CLASS
            NAME "Pixel retenu par le scenario q70"
            EXPRESSION "1"
            STYLE
                COLOR 0 0 0
            END
        END

        CLASS
            NAME "Pixel non retenu - transparent"
            EXPRESSION "0"
            STYLE
                COLOR 255 255 255
                OPACITY 0
            END
        END

        METADATA
            "wms_title" "Pixels retenus - scenario q70"
            "wms_abstract" "Couche raster intermediaire. La valeur 1 identifie les pixels retenus par le scenario q70 ; la valeur 0 est transparente."
            "wms_srs" "EPSG:31370"
        END
    END


    # -------------------------------------------------------------------------
    # Raster intermediaire q90 : 0 transparent ; 1 noir.
    # -------------------------------------------------------------------------
    LAYER
        NAME "ogf_q90_pixels_retenus"
        TYPE RASTER
        STATUS ON

        DATA "ogf_q90_pixels_retenus.tif"

        PROJECTION
            "init=epsg:31370"
        END

        PROCESSING "BANDS=1"
        CLASSITEM "[pixel]"

        CLASS
            NAME "Pixel retenu par le scenario q90"
            EXPRESSION "1"
            STYLE
                COLOR 0 0 0
            END
        END

        CLASS
            NAME "Pixel non retenu - transparent"
            EXPRESSION "0"
            STYLE
                COLOR 255 255 255
                OPACITY 0
            END
        END

        METADATA
            "wms_title" "Pixels retenus - scenario q90"
            "wms_abstract" "Couche raster intermediaire. La valeur 1 identifie les pixels retenus par le scenario q90 ; la valeur 0 est transparente."
            "wms_srs" "EPSG:31370"
        END
    END


